  privacy_s7_p: { fr: "Ce site utilise uniquement des cookies techniques, nécessaires à son fonctionnement :",
    es: "Este sitio utiliza únicamente cookies técnicas, necesarias para su funcionamiento:",
    en: "This site only uses technical cookies, necessary for it to work:" },
